using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "FlammableChakramEffect", menuName = "Data/Battle/Effects/Sothis/FlammableChakram Effect")]
public class FlammableChakramEffect : Effect
{
	[Header("Relief")]
	[SerializeField]
	private ReliefDefaultEffectAction reliefDefaultEffectAction;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string localizedDescription = GetLocalizedDescription();
		if (amount == EffectsValues.NO_VALUE)
		{
			amount = -1;
		}
		return Smart.Format(localizedDescription, reliefDefaultEffectAction.GetActionDescription(amount).LowercaseFirst()) + AppendedDescription();
	}

	public void ApplyRelief(GameObject target, int effectAmount)
	{
		reliefDefaultEffectAction.CastTargetAmount(target, effectAmount, null);
	}
}
